WITH input_rows ( id, link_id, provider_label_id, name, message_list_visibility, label_list_visibility, type ) AS ( SELECT * FROM unnest( $1::uuid[], $2::uuid[], $3::text[], $4::text[], $5::email_message_list_visibility_enum[], $6::email_label_list_visibility_enum[], $7::email_label_type_enum[] ) ) INSERT INTO email_labels ( id, link_id, provider_label_id, name, message_list_visibility, label_list_visibility, type ) SELECT id, link_id, provider_label_id, name, message_list_visibility, label_list_visibility, type FROM input_rows ON CONFLICT (link_id, provider_label_id) DO UPDATE SET name = EXCLUDED.name, message_list_visibility = EXCLUDED.message_list_visibility, label_list_visibility = EXCLUDED.label_list_visibility, type = EXCLUDED.type
